export const NEEDS_VS_WANTS_ACTIVITIES = [
{n:1,type:"mcq",micro:"Apa itu kebutuhan",q:"'Kebutuhan' adalah...",options:["Hal yang benar-benar diperlukan untuk hidup, kesehatan, atau bersekolah","Hal yang membuat hidup lebih menyenangkan tapi bisa ditunda dulu tanpa masalah","Barang termahal yang dipakai pelajar untuk menunjukkan kemampuan ekonomi keluarga"],answer:0,explain:"Kebutuhan menopang kehidupan & kegiatan pentingmu. Tanpanya, ada masalah serius.",hint:"Apa yang terjadi kalau kamu TIDAK punya ini sama sekali?"},
{n:2,type:"mcq",micro:"Apa itu keinginan",q:"'Keinginan' adalah...",options:["Sesuatu yang tak berguna bagi orang mana pun dan sebaiknya segera dibuang atau dilupakan","Hal yang menambah kesenangan atau kenyamanan tapi hidup tetap berjalan tanpanya","Hal yang wajib dimiliki setiap orang, dan hidupnya tetap berjalan baik"],answer:1,explain:"Keinginan itu sah & manusiawi, tapi bukan syarat untuk hidup & sehat.",hint:"Kalau kamu tidak membelinya, apakah hidupmu tetap baik-baik saja?"},
{n:3,type:"mcq",micro:"Contoh kebutuhan",q:"Manakah yang paling jelas merupakan kebutuhan bagi seorang pelajar?",options:["Konsol gim terbaru yang sedang populer","Sepatu edisi terbatas dari merek yang sedang terkenal","Makanan bergizi & seragam sekolah yang layak"],answer:2,explain:"Makanan & pakaian sekolah menopang kesehatan & kegiatan belajar; dua pilihan lainnya menambah kesenangan.",hint:"Mana yang kamu perlukan untuk tetap sehat & bersekolah?"},
{n:4,type:"mcq",micro:"Contoh keinginan",q:"Manakah yang paling jelas merupakan keinginan?",options:["Camilan mahal edisi khusus","Buku pelajaran wajib","Air minum bersih"],answer:0,explain:"Camilan edisi khusus menyenangkan tapi tidak diperlukan; air & buku pelajaran adalah kebutuhan.",hint:"Mana yang tidak akan menimbulkan masalah kalau tidak kamu miliki?"},
{n:5,type:"classify",micro:"Kebutuhan atau keinginan",q:"Kelompokkan tiap barang sebagai 'Kebutuhan' atau 'Keinginan' untuk seorang pelajar dalam keadaan biasa.",items:["Alat tulis untuk sekolah","Mainan koleksi terbaru","Makan siang sehat","Kaus band favorit"],groups:["Kebutuhan","Keinginan"],answer:{"Kebutuhan":["Alat tulis untuk sekolah","Makan siang sehat"],"Keinginan":["Mainan koleksi terbaru","Kaus band favorit"]},explain:"Kebutuhan menopang kesehatan & belajar; keinginan menambah kesenangan.",hint:"Tanya untuk tiap item: 'Apa akibatnya kalau aku tidak punya ini?'"},
{n:6,type:"mcq",micro:"Kebutuhan tergantung situasi",q:"Payung adalah kebutuhan atau keinginan?",options:["Kebutuhan; semua barang yang dipakai ke sekolah termasuk kebutuhan","Tergantung: saat musim hujan & harus jalan kaki ke sekolah, lebih ke kebutuhan","Keinginan; barang itu hanya melengkapi penampilan saat berangkat ke sekolah pada pagi hari"],answer:1,explain:"Beberapa barang berpindah kategori tergantung keadaan. Menilai konteks lebih tepat daripada label kaku.",hint:"Apakah payung sama pentingnya di kemarau & di musim hujan?"},
{n:7,type:"order",micro:"Memilih saat uang terbatas",q:"Uangmu terbatas bulan ini. Urutkan prioritas pengeluaran yang masuk akal.",items:["Kebutuhan pokok (makan, transport sekolah, alat wajib)","Kewajiban (bayar utang, iuran yang disepakati)","Tabungan/cadangan","Keinginan (hiburan, jajan tambahan)"],answer:[0,1,2,3],explain:"Saat sempit, dahulukan yang menjaga hidup berjalan & kewajiban, lalu menabung, baru keinginan.",hint:"Mana yang tidak bisa ditunda tanpa masalah serius?"},
{n:8,type:"mcq",micro:"Keinginan yang menyamar jadi kebutuhan",q:"'Aku BUTUH sepatu edisi baru itu' — sering kata 'butuh' di sini sebenarnya berarti...",options:["Perintah dari toko yang harus dituruti, lalu sepatu lama diganti dengan yang baru oleh pembeli","Benar-benar kebutuhan hidup; sepatu baru lebih baik daripada sepatu lama","Keinginan yang kuat; sepatu lama yang masih layak sudah memenuhi kebutuhan sebenarnya"],answer:2,explain:"Kita sering memakai kata 'butuh' untuk keinginan yang kuat. Cek apakah kebutuhan dasarnya sudah terpenuhi.",hint:"Apakah sepatu yang sekarang masih bisa dipakai ke sekolah?"},
{n:9,type:"mcq",micro:"Keinginan itu sah",q:"Apakah salah memiliki keinginan & sesekali membelinya?",options:["Tidak — keinginan itu manusiawi & wajar; masalahnya hanya kalau keinginan mengalahkan kebutuhan atau membuatmu berutang","Ya, salah — semua keinginan harus dihindari; uangmu tidak cepat habis dan kamu tidak berutang, itu cara aman","Ya, salah — hanya kebutuhan yang boleh dibeli, sedangkan keinginan sekecil apa saja termasuk perilaku buruk yang harus dihentikan"],answer:0,explain:"Mengelola uang yang sehat menyertakan porsi untuk kesenangan. Tujuannya keseimbangan, bukan pantang total.",hint:"Apakah rencana yang tidak pernah membolehkan kesenangan bisa bertahan lama?"},
{n:10,type:"mcq",micro:"Kebutuhan dulu, keinginan kemudian",q:"Prinsip pengeluaran yang sehat:",options:["Abaikan kebutuhan demi keinginan lebih dulu, lalu tabungan dan kewajiban dipikirkan belakangan saja","Penuhi kebutuhan & kewajiban dulu, sisihkan tabungan, baru pakai sisanya untuk keinginan","Beli semua keinginan dulu selagi masih ada uang di dompet, sisanya baru dipakai untuk kebutuhan"],answer:1,explain:"Mendahulukan kebutuhan & tabungan melindungi kamu; keinginan dipenuhi dari sisa yang aman.",hint:"Apa yang kamu lindungi lebih dulu?"},
{n:11,type:"tf",micro:"Kebutuhan berbeda antar orang",q:"Benar atau Salah: Apa yang menjadi kebutuhan bisa sedikit berbeda antar orang tergantung keadaan (pekerjaan orang tua, jarak sekolah, kondisi kesehatan).",answer:true,explain:"Contoh: bagi siswa yang tinggal jauh, sepeda bisa jadi kebutuhan transport; bagi yang dekat, keinginan.",hint:"Apakah kebutuhan anak di desa terpencil sama persis dengan anak di kota?"},
{n:12,type:"mcq",micro:"Membedakan sebelum membeli",q:"Sebelum membeli sesuatu, pertanyaan yang membantu memilah:",options:["'Apakah barang ini terlihat keren dan teman-teman akan memujiku di sekolah besok pagi, dan apakah banyak yang sudah membelinya?'","'Apakah temanku sudah punya barang yang sama, dan apakah mereka akan menganggapku ketinggalan zaman bila belum membelinya?'","'Apakah ini kebutuhan atau keinginan? Kalau keinginan, apakah aku masih menginginkannya besok & apakah anggaranku cukup?'"],answer:2,explain:"Menamai jenis pembelian & menjeda sebelum keinginan yang mahal membantu keputusan yang tenang.",hint:"Apa yang membedakan pembelian yang disengaja dari yang impulsif?"},
{n:13,type:"mcq",micro:"Kebutuhan yang terlupakan",q:"Kalau kamu menghabiskan uang saku untuk keinginan di awal minggu lalu tidak punya uang transport di akhir minggu, ini menunjukkan...",options:["Kebutuhan (transport) seharusnya diamankan lebih dulu sebelum keinginan","Tidak ada masalah; uang saku bisa dipakai untuk apa saja kapan pun","Transport bukan kebutuhan; anak bisa berjalan kaki ke mana saja walau jaraknya jauh"],answer:0,explain:"Menyisihkan uang untuk kebutuhan rutin lebih dulu mencegah 'kehabisan' di saat penting.",hint:"Apa yang terjadi kalau uang kebutuhan dipakai untuk keinginan?"},
{n:14,type:"mcq",micro:"Kualitas kebutuhan",q:"Untuk kebutuhan seperti sepatu sekolah, pilihan yang bijak biasanya...",options:["Yang termahal dan bermerek terkenal, karena harga tinggi menjamin sepatu tahan lama bertahun-tahun, dan terlihat bergengsi","Yang cukup nyaman & tahan lama dengan harga wajar — bukan yang termurah yang cepat rusak, bukan yang termahal karena merek","Yang termurah di toko, karena sepatu hanya dipakai di sekolah dan tak perlu dipikirkan kualitasnya, yang penting bisa dipakai"],answer:1,explain:"Untuk kebutuhan, nilai (daya tahan + kenyamanan ÷ harga) lebih penting daripada harga terendah atau merek.",hint:"Sepatu Rp50.000 yang rusak sebulan vs Rp150.000 yang tahan setahun — mana lebih hemat?"},
{n:15,type:"tf",micro:"Menabung juga prioritas",q:"Benar atau Salah: Tabungan sebaiknya diperlakukan sebagai 'sisa yang kalau ada' setelah semua kebutuhan & keinginan terbeli, bukan sesuatu yang disisihkan lebih dulu.",answer:false,explain:"Sebaliknya — tabungan sebaiknya dianggap hampir sepenting kebutuhan & disisihkan di awal. Kalau menunggu sisa, sering tidak ada sisa; menyisihkan di depan membuatnya lebih pasti & melindungimu dari keadaan darurat.",hint:"Kapan kemungkinan besar masih ada uang untuk ditabung — di awal atau di akhir?"},
{n:16,type:"mcq",micro:"Keinginan yang bertahan lama vs sesaat",q:"Cara membedakan keinginan yang 'benar-benar kamu inginkan' dari 'dorongan sesaat':",options:["Beli segera sebelum kamu berubah pikiran; keinginan yang ditunda biasanya hilang dan kesempatan lewat","Semua keinginan itu sesaat, jadi tak ada keinginan yang layak dipertimbangkan, ditabung, atau dibeli nanti","Tunggu beberapa hari; kalau masih sangat kamu inginkan & masuk anggaran, kemungkinan itu keinginan sejati"],answer:2,explain:"Dorongan membeli sering memudar setelah beberapa jam/hari. Menunggu memisahkan keinginan sejati dari impuls.",hint:"Apakah semua yang sangat kamu inginkan sekarang masih kamu inginkan minggu depan?"},
{n:17,type:"mcq",micro:"Berbagi & memberi",q:"Menyisihkan sebagian kecil untuk membantu orang lain (menyumbang, membantu teman)...",options:["Adalah pilihan pribadi yang banyak orang anggap bagian dari mengelola uang dengan baik","Pemborosan; uang yang dipakai untuk bersenang-senang tak bisa kembali lagi","Wajib 50% dari semua uang yang kamu terima setiap bulan dari orang tuamu sendiri atau dari siapa pun"],answer:0,explain:"Banyak rencana keuangan menyertakan porsi 'berbagi'. Besarnya adalah pilihan sesuai nilai & kemampuan.",hint:"Apakah mengelola uang hanya tentang diri sendiri?"},
{n:18,type:"mcq",micro:"Kebutuhan keluarga vs pribadi",q:"Uang saku biasanya untuk keperluan pribadimu. Kebutuhan besar keluarga (listrik, sewa, makan pokok)...",options:["Bukan urusan orang di rumah, dan tagihan dibiarkan menunggu sampai ada yang sempat membayarnya","Ditanggung orang tua/wali; kamu bisa membantu dengan tidak boros & memahami keadaan keluarga","Harus kamu bayar dari uang saku tiap bulan, walau uang sakumu jauh lebih kecil dari tagihannya"],answer:1,explain:"Memahami peran uang saku (keperluan pribadi & belajar mengelola) & menghargai kerja orang tua adalah bagian dari literasi keuangan.",hint:"Siapa yang biasanya menanggung tagihan besar rumah tangga?"},
{n:19,type:"mcq",micro:"Menilai iklan",q:"Iklan sering membuat keinginan terasa seperti kebutuhan dengan cara...",options:["Memberi informasi netral dan jujur tentang kekurangan produk yang diiklankan itu kepada penonton","Menyuruhmu menabung dulu sebelum membeli produk yang ditawarkan di iklan tersebut","Menampilkan orang bahagia/populer memakai produk & menyiratkan 'kamu kurang tanpa ini'"],answer:2,explain:"Iklan dirancang membangkitkan keinginan. Menyadari ini membantumu memisahkan 'aku ingin' dari 'aku butuh'.",hint:"Apa yang iklan ingin kamu rasakan tentang dirimu tanpa produk itu?"},
{n:20,type:"open",micro:"Memilah pengeluaranmu",q:"Tuliskan 6 hal yang kamu belanjakan dengan uangmu dalam sebulan terakhir. Untuk tiap satu, tandai 'Kebutuhan', 'Keinginan', atau 'Campuran', & beri alasan singkat.",explain:"Jawaban baik menilai tiap pengeluaran berdasarkan 'apa akibatnya kalau tidak ada ini', mengenali kategori 'campuran', & jujur pada diri sendiri.",hint:"Untuk tiap item: apa yang terjadi kalau kamu tidak membelinya?",sample:"Contoh: (1) Ongkos angkot ke sekolah — Kebutuhan (harus, untuk bersekolah). (2) Nasi + lauk di kantin — Kebutuhan (makan siang; tapi kalau pilih yang mahal karena gengsi, ada unsur keinginan). (3) Es teh kemasan tiap hari — Keinginan (air minum dari rumah cukup). (4) Buku tulis baru — Kebutuhan (yang lama habis). (5) Stiker & pulpen warna-warni — Campuran (pulpen dasar kebutuhan, versi warna-warni & banyak adalah keinginan). (6) Top up gim — Keinginan (hiburan, hidup tetap jalan tanpanya)."},
{n:21,type:"mcq",micro:"Mengapa membedakan penting",q:"Membedakan kebutuhan & keinginan membantu karena...",options:["Saat uang terbatas, kamu tahu apa yang harus diamankan lebih dulu & di mana bisa berhemat tanpa masalah serius","Membuat belanja jadi lebih rumit dan memakan waktu tanpa manfaat bagi pengelolaan uang kamu sehari-hari","Tidak ada gunanya; semua pengeluaran sama saja dan uangnya habis di akhir bulan, jadi tak perlu dipilah"],answer:0,explain:"Ketika harus memangkas, memotong keinginan berdampak kecil; memotong kebutuhan menimbulkan masalah.",hint:"Bagian mana yang lebih aman dikurangi saat uang menipis?"},
{n:22,type:"mcq",micro:"Biaya peluang",q:"Kamu punya Rp30.000 & memilih membeli komik. 'Biaya peluang'-nya adalah...",options:["Harga komik ditambah pajak dan ongkos kirim bila membeli lewat toko daring, ditambah biaya admin dan biaya kemasan","Hal terbaik berikutnya yang tidak jadi kamu lakukan dengan uang itu (mis. menabung untuk sepatu bola)","Rp30.000 uang tunai yang keluar dari dompet saat kamu membayar di kasir toko buku itu"],answer:1,explain:"Setiap keputusan uang berarti melepaskan pilihan lain. Menyadarinya membuat pilihan lebih jujur.",hint:"Apa yang kamu korbankan dengan memilih komik?"},
{n:23,type:"mcq",micro:"Keinginan hari ini vs kebutuhan nanti",q:"Menghabiskan semua untuk keinginan hari ini bisa berarti...",options:["Tak ada risiko; uang saku otomatis diisi ulang oleh orang tua setiap kali habis","Kebutuhan tak akan muncul lagi minggu depan, jadi seluruh uang aman dihabiskan sekarang","Tidak ada dana untuk kebutuhan mendadak minggu depan (alat sekolah rusak, sakit)"],answer:2,explain:"Kebutuhan tak terduga hampir selalu muncul. Menyisakan cadangan melindungimu.",hint:"Apa yang terjadi kalau tasmu jebol & uangmu sudah habis untuk jajan?"},
{n:24,type:"classify",micro:"Kebutuhan, keinginan, atau tabungan",q:"Kelompokkan tiap alokasi uang saku ke 'Kebutuhan', 'Keinginan', atau 'Tabungan'.",items:["Ongkos transport harian","Menyisihkan Rp10.000 tiap minggu untuk sepeda","Membeli minuman boba mingguan","Membeli makan siang di kantin"],groups:["Kebutuhan","Keinginan","Tabungan"],answer:{"Kebutuhan":["Ongkos transport harian","Membeli makan siang di kantin"],"Keinginan":["Membeli minuman boba mingguan"],"Tabungan":["Menyisihkan Rp10.000 tiap minggu untuk sepeda"]},explain:"Anggaran sederhana membagi uang ke tiga kelompok ini (kadang plus 'berbagi').",hint:"Apakah ini menjaga hidup berjalan, menambah kesenangan, atau untuk nanti?"},
{n:25,type:"mcq",micro:"Penundaan kepuasan",q:"'Menunda kepuasan' berarti...",options:["Menahan diri dari kesenangan kecil sekarang demi sesuatu yang lebih besar/penting nanti","Tidak menikmati apa pun sepanjang hidup, bahkan ketika uangnya sudah lebih dari cukup","Membeli semua yang diinginkan sekaligus hari ini sebelum harganya naik dan habis di toko"],answer:0,explain:"Kemampuan menunda kepuasan sangat berkaitan dengan keberhasilan menabung & mencapai tujuan.",hint:"Satu permen sekarang, atau dua permen kalau menunggu 15 menit — mana yang kamu pilih & mengapa?"},
{n:26,type:"mcq",micro:"Keinginan yang jadi kebiasaan mahal",q:"Jajan Rp5.000 setiap hari sekolah (5 hari) selama 4 minggu berjumlah...",options:["Rp25.000","Rp100.000","Rp20.000"],answer:1,explain:"Rp5.000 × 5 × 4 = Rp100.000. Keinginan kecil yang rutin menjadi jumlah besar. Menyadari totalnya membantu memutuskan.",hint:"Hitung per minggu, lalu kalikan 4."},
{n:27,type:"mcq",micro:"Menukar keinginan dengan tujuan",q:"Kalau kamu mengurangi jajan Rp100.000/bulan menjadi Rp40.000, kamu bisa...",options:["Tak berdampak pada tabunganmu; uang yang dihemat dari jajan hilang begitu saja tanpa bekas","Kehilangan semua kesenangan dan tak bisa jajan lagi sepanjang bulan, jadi pengurangan itu dihindari","Menabung Rp60.000/bulan menuju tujuan (sepeda, kursus) tanpa menghilangkan kesenangan sepenuhnya"],answer:2,explain:"Mengurangi (bukan menghapus) keinginan tertentu membebaskan uang untuk tujuan yang lebih kamu pedulikan.",hint:"Apa yang bisa kamu capai dengan Rp60.000 lebih per bulan?"},
{n:28,type:"tf",micro:"Kebutuhan bisa dipenuhi dengan cara lebih murah",q:"Benar atau Salah: Sebuah kebutuhan hanya bisa dipenuhi dengan satu cara yang biayanya tetap — tidak ada pilihan yang lebih murah.",answer:false,explain:"Kebutuhan sering bisa dipenuhi dengan beberapa cara berbiaya berbeda. Contoh: 'bergerak ke sekolah' bisa lewat jalan kaki, sepeda, angkot, atau diantar. Memilih cara yang lebih murah tetap memenuhi kebutuhan.",hint:"Apakah 'makan siang' harus selalu berupa yang termahal di kantin?"},
{n:29,type:"mcq",micro:"Keinginan sebagai motivasi",q:"Keinginan (mis. sepeda baru) bisa berguna dalam mengelola uang sebagai...",options:["Tujuan tabungan yang memotivasi kamu menyisihkan uang secara teratur","Alasan berutang kepada teman, lalu keinginan itu bisa langsung terbeli","Hal yang harus diabaikan; keinginan tak boleh dipikirkan sama sekali"],answer:0,explain:"Keinginan yang jelas & bernilai bisa jadi tujuan tabungan yang membuat menabung terasa berarti.",hint:"Lebih mudah menabung 'untuk apa saja' atau 'untuk sepeda yang sangat kamu inginkan'?"},
{n:30,type:"order",micro:"Menghadapi keinginan yang mahal",q:"Kamu sangat ingin sesuatu yang mahal. Urutkan langkah yang bijak.",items:["Tunggu beberapa hari; cek apakah kamu masih menginginkannya","Periksa: apakah kebutuhan & tabungan bulan ini sudah aman?","Hitung: berapa lama menabung untuk ini, & apa biaya peluangnya","Putuskan: menabung untuk itu, memilih versi lebih murah, atau melewatinya"],answer:[0,1,2,3],explain:"Jeda → cek kebutuhan & tabungan → hitung waktu & biaya peluang → putuskan dengan tenang.",hint:"Jangan putuskan di puncak keinginan."},
{n:31,type:"mcq",micro:"Kebutuhan yang berubah seiring usia",q:"Kebutuhan seseorang anak SD & seorang siswa SMA...",options:["Sepenuhnya berbeda; SMP dan SMA punya kebutuhan yang tak punya kesamaan, jadi perlu disiapkan terpisah oleh orang tua","Sebagian sama (makan, kesehatan, pakaian) & sebagian berbeda (SMA mungkin butuh alat/buku yang lebih spesifik, transport lebih jauh)","Persis sama; kebutuhan seorang pelajar tidak berubah dari SMP sampai SMA, termasuk buku, alat, dan transport harian"],answer:1,explain:"Kebutuhan dasar tetap, tapi detailnya berkembang. Meninjau ulang 'apa yang benar-benar kubutuhkan sekarang' itu wajar.",hint:"Apakah kebutuhan sekolahmu sama dengan saat kamu kelas 1?"},
{n:32,type:"mcq",micro:"Tekanan teman & keinginan",q:"Teman-teman punya barang X & kamu merasa 'harus punya juga'. Sebelum membeli:",options:["Beli segera agar kamu tidak dianggap ketinggalan zaman, karena persahabatan lebih penting daripada anggaran","Pinjam uang dari kakak atau teman untuk membelinya sekarang, lalu pikirkan cara mengembalikannya belakangan","Tanya: apakah aku benar-benar menginginkannya untuk diriku, atau hanya karena takut berbeda? Apakah masuk anggaranku?"],answer:2,explain:"Tekanan sosial bisa mengubah keinginan orang lain jadi 'kebutuhan' palsu dalam pikiranmu.",hint:"Apakah kamu memilih ini untuk dirimu, atau untuk terlihat sama dengan yang lain?"},
{n:33,type:"tf",micro:"Tidak semua kebutuhan harus dibeli",q:"Benar atau Salah: Satu-satunya cara memenuhi sebuah kebutuhan adalah dengan membeli barang baru — meminjam, memakai ulang, atau berbagi tidak dihitung.",answer:false,explain:"'Memenuhi kebutuhan' tidak selalu berarti 'membeli baru'. Meminjam buku dari perpustakaan, memakai barang yang masih ada, atau berbagi dengan teman/keluarga sering cukup.",hint:"Apakah kamu harus membeli buku yang hanya dipakai seminggu?"},
{n:34,type:"mcq",micro:"Keinginan yang menghabiskan tujuan",q:"Kamu sudah menabung 8 minggu untuk sepeda (kurang 2 minggu lagi), lalu tergoda memakai tabungan itu untuk keinginan lain. Pertimbangan:",options:["Ingat berapa lama & susah kamu menabung; keinginan sesaat ini kemungkinan tidak sepadan dengan mundurnya tujuan besar","Pakai saja tabungan itu sekarang; sepeda bisa dibeli nanti dan keinginan baru ini lebih menyenangkan","Tabungan memang dibuat untuk dihabiskan kapan saja, jadi tidak perlu mempertimbangkan tujuan awal menabungmu"],answer:0,explain:"Godaan sering muncul justru saat tujuan hampir tercapai. Mengingat usaha yang sudah dikeluarkan membantu bertahan.",hint:"Apa yang kamu korbankan kalau memakai tabungan sepeda sekarang?"},
{n:35,type:"mcq",micro:"Membedakan bantu keputusan cepat",q:"Di toko, dengan waktu & uang terbatas, memilah cepat 'kebutuhan dulu' membantu karena...",options:["Tidak ada gunanya di toko; semua barang di rak sudah dipilih oleh penjual untuk dibeli pengunjung","Kamu pasti pulang membawa yang penting, & sisa uang/waktu untuk keinginan bila ada","Membuat belanja menjadi lebih lama dan melelahkan, dan uang justru lebih cepat habis di toko"],answer:1,explain:"Prioritas yang jelas melindungi dari 'kehabisan uang untuk hal penting karena membeli keinginan dulu'.",hint:"Apa yang kamu ambil pertama kalau uangmu mungkin tidak cukup untuk semuanya?"},
{n:36,type:"mcq",micro:"Nilai vs harga pada keinginan",q:"Untuk keinginan (mis. mainan, aksesori), 'nilai' bagimu adalah...",options:["Sama dengan harganya; barang yang lebih mahal lebih bernilai bagi pembeli mana pun, dan harga mencerminkan nilai","Lebih tinggi dari harganya; keinginan yang kamu beli otomatis membuatmu lebih bahagia dari yang lain sepanjang waktu","Seberapa banyak kesenangan/kegunaan yang benar-benar kamu dapat dibanding harganya & hal lain yang bisa kamu beli"],answer:2,explain:"Keinginan mahal yang cepat bosan memberi 'nilai' rendah; keinginan murah yang lama dinikmati memberi 'nilai' tinggi.",hint:"Berapa lama kamu benar-benar akan menikmati barang ini?"},
{n:37,type:"tf",micro:"Anggaran menyertakan keinginan",q:"Benar atau Salah: Anggaran yang baik biasanya menyisakan porsi khusus untuk keinginan/kesenangan, bukan hanya kebutuhan & tabungan.",answer:true,explain:"Anggaran tanpa ruang untuk kesenangan sulit dijalani lama. Porsi keinginan yang direncanakan membuat pengeluaran itu disengaja, bukan diam-diam.",hint:"Bisakah kamu menaati anggaran yang tidak pernah membolehkan hal menyenangkan?"},
{n:38,type:"mcq",micro:"Keinginan orang lain bukan kebutuhanmu",q:"Toko/aplikasi menampilkan 'orang yang membeli X juga membeli Y'. Ini...",options:["Saran untuk membuatmu membeli lebih banyak; belum tentu kamu membutuhkan atau menginginkan Y","Daftar kebutuhanmu yang disusun toko berdasarkan hasil riset keluarga di kota besar","Perintah yang harus diikuti pembeli, dan sudah ditulis sebagai rekomendasi resmi"],answer:0,explain:"Rekomendasi belanja melayani penjual. Putuskan berdasarkan kebutuhan & keinginanmu sendiri.",hint:"Siapa yang diuntungkan kalau kamu membeli barang tambahan?"},
{n:39,type:"mcq",micro:"Merefleksikan pengeluaran",q:"Di akhir bulan, melihat berapa yang habis untuk keinginan berguna untuk...",options:["Tak ada gunanya; uang itu sudah lewat dan tak bisa diubah atau diperbaiki lagi, jadi lupakan saja","Menyadari pola (mungkin lebih besar dari yang dikira) & memutuskan apakah ingin menyesuaikan bulan depan","Menghukum diri sendiri dan menyalahkan diri atas setiap pembelian keinginan yang sudah dilakukan bulan ini"],answer:1,explain:"Melihat total pengeluaran keinginan sering mengejutkan & membantu keputusan sadar ke depan.",hint:"Bagaimana kamu tahu ke mana uangmu pergi tanpa melihatnya?"},
{n:40,type:"open",micro:"Menukar keinginan dengan tujuan",q:"Kamu ingin mengumpulkan Rp360.000 untuk sebuah kursus dalam 3 bulan. Uang sakumu Rp80.000/minggu, & saat ini kamu menghabiskan sekitar Rp40.000/minggu untuk keinginan (jajan tambahan, top up, dll.). Buat rencana: berapa yang bisa kamu sisihkan, keinginan mana yang kamu kurangi (bukan hapus), & berapa lama sampai tercapai.",explain:"Jawaban baik menghitung target mingguan, memilih keinginan spesifik untuk dikurangi (bukan menghapus semua), menyisakan sedikit untuk kesenangan agar berkelanjutan, & menghitung durasi.",hint:"Kurangi keinginan tertentu secukupnya untuk mencapai target — jangan hapus semua kesenangan sekaligus.",sample:"Butuh Rp360.000 ÷ 3 bulan = Rp120.000/bulan = Rp30.000/minggu. Aku bisa menyisihkan Rp30.000/minggu kalau mengurangi pengeluaran keinginan dari Rp40.000 jadi Rp10.000/minggu. Keinginan yang kukurangi: top up gim (dari Rp20.000 jadi Rp0 selama 3 bulan) & jajan minuman kemasan (dari Rp15.000 jadi Rp5.000, bawa minum dari rumah). Aku tetap sisakan Rp10.000/minggu untuk keinginan kecil agar tidak jenuh. Dengan Rp30.000/minggu × 12 minggu = Rp360.000, tercapai tepat 3 bulan. Kalau ada uang lebih (hadiah, bantu paman), kupercepat."},
{n:41,type:"mcq",micro:"Pengeluaran berbasis nilai",q:"'Pengeluaran berbasis nilai' berarti...",options:["Menghabiskan seluruh uang pada hal yang disukai tanpa memikirkan kebutuhan atau tabungan; hidup cuma sekali","Tak membeli apa-apa; semua pengeluaran dianggap boros dan harus dikurangi menjadi nol tiap bulan dalam waktu dekat","Membelanjakan lebih banyak pada hal yang benar-benar penting bagimu & memangkas yang tidak — bukan sekadar 'hemat di segala hal'"],answer:2,explain:"Alih-alih pelit merata, arahkan uang ke hal yang paling kamu hargai (mis. buku, hobi tertentu) & potong yang tidak berarti bagimu.",hint:"Di mana uangmu paling 'terasa berguna' bagimu, & di mana ia terbuang tanpa disadari?"},
{n:42,type:"mcq",micro:"Aturan pribadi untuk keinginan",q:"Contoh 'aturan pribadi' yang membantu mengelola pembelian keinginan:",options:["'Untuk keinginan di atas Rp25.000, tunggu 2 hari; kalau masih mau & anggaran keinginan cukup, baru beli'","'Beli semua yang menarik di toko atau media sosial; kesempatan belum tentu datang dua kali'","'Jangan membeli apa-apa untuk kesenangan; tiap rupiah harus disimpan untuk masa depanmu dan keluargamu kelak'"],answer:0,explain:"Aturan yang jelas mengubah pembelian keinginan dari refleks menjadi keputusan sadar, tanpa melarang total.",hint:"Apa aturan singkat yang bisa kamu jadikan kebiasaan?"},
{n:43,type:"mcq",micro:"Kebutuhan yang bertentangan",q:"Bulan ini kamu butuh sepatu sekolah baru (yang lama rusak) DAN buku pelajaran wajib, tapi uang hanya cukup untuk satu. Langkah yang masuk akal:",options:["Abaikan keduanya dan tunggu sampai ada orang lain yang menawarkan bantuan tanpa diminta, sambil tetap datang ke sekolah","Cari cara: pinjam/beli buku bekas, perbaiki sepatu sementara, minta bantuan keluarga, atau atur agar keduanya terpenuhi bertahap","Beli keinginan dulu karena itu yang paling membuat semangat belajar, kebutuhan menyusul belakangan saat uang ada"],answer:1,explain:"Ketika dua kebutuhan bertabrakan, cari solusi kreatif (bekas, pinjam, perbaikan, bantuan, bertahap) sebelum menyerah pada salah satu.",hint:"Apakah keduanya harus dibeli baru & sekaligus?"},
{n:44,type:"mcq",micro:"Keinginan sebagai hadiah untuk diri",q:"Sesekali membelanjakan uang untuk keinginan setelah mencapai tujuan (mis. selesai ujian, target tabungan)...",options:["Buruk; setiap hadiah untuk diri sendiri merusak anggaran bulanan dan membuat kita boros","Wajib setelah setiap hal kecil yang berhasil kamu kerjakan di sekolah atau rumah sehari-hari","Bisa sehat sebagai 'hadiah' yang direncanakan & terjangkau — menjaga semangat tanpa merusak anggaran"],answer:2,explain:"Hadiah kecil yang direncanakan & sesuai anggaran menjaga motivasi. Yang bermasalah adalah hadiah impulsif yang mahal & sering.",hint:"Apa bedanya 'hadiah terencana yang terjangkau' & 'menghabiskan tabungan karena impuls'?"},
{n:45,type:"classify",micro:"Menilai pembelian",q:"Kelompokkan tiap pembelian sebagai 'Kebutuhan yang bijak', 'Keinginan yang direncanakan (oke)', atau 'Pembelian impulsif (waspada)'.",items:["Membeli buku bekas yang wajib untuk kelas, harga wajar","Membeli tiket konser yang sudah kamu tabung khusus selama 2 bulan","Membeli mainan mahal di kasir karena 'kelihatan asik' padahal tidak direncanakan"],groups:["Kebutuhan yang bijak","Keinginan yang direncanakan (oke)","Pembelian impulsif (waspada)"],answer:{"Kebutuhan yang bijak":["Membeli buku bekas yang wajib untuk kelas, harga wajar"],"Keinginan yang direncanakan (oke)":["Membeli tiket konser yang sudah kamu tabung khusus selama 2 bulan"],"Pembelian impulsif (waspada)":["Membeli mainan mahal di kasir karena 'kelihatan asik' padahal tidak direncanakan"]},explain:"Keinginan yang direncanakan & ditabung berbeda dari impuls; kebutuhan yang dibeli dengan cerdik (bekas, harga wajar) adalah pengelolaan yang baik.",hint:"Apakah pembelian ini direncanakan & sesuai kategorinya?"},
{n:46,type:"mcq",micro:"Kebutuhan darurat & dana darurat",q:"'Dana darurat' berhubungan dengan kebutuhan karena...",options:["Ia menutup kebutuhan mendadak (alat sekolah rusak, sakit, kehilangan) tanpa memaksamu berutang atau mengorbankan kebutuhan lain","Ia khusus dipakai membeli keinginan yang sedang populer, dan kamu tidak ketinggalan dari teman; itu tujuannya","Ia tak boleh disentuh, bahkan ketika alat sekolahmu rusak atau kamu sakit dan butuh biaya; itu aturannya"],answer:0,explain:"Dana darurat adalah tabungan khusus untuk kebutuhan tak terduga — penyangga yang memberi rasa aman.",hint:"Untuk apa uang yang sengaja disimpan & hanya dipakai saat mendesak?"},
{n:47,type:"order",micro:"Menyusun prioritas pengeluaran bulanan",q:"Urutkan langkah menyusun prioritas pengeluaran untuk satu bulan.",items:["Daftar kebutuhan tetap (transport, makan, alat wajib) & perkirakan biayanya","Tetapkan jumlah tabungan yang disisihkan di awal","Alokasikan sisa untuk keinginan & berbagi, dengan batas yang jelas","Pantau selama bulan berjalan & sesuaikan bila perlu"],answer:[0,1,2,3],explain:"Kebutuhan → tabungan → keinginan & berbagi (dengan batas) → pantau.",hint:"Amankan kebutuhan & tabungan sebelum mengalokasikan keinginan."},
{n:48,type:"mcq",micro:"Ketika keinginan menjadi kebutuhan seiring waktu",q:"Ponsel bagi sebagian siswa dulu keinginan, kini bisa jadi kebutuhan (komunikasi, tugas daring). Ini menunjukkan...",options:["Ponsel merupakan keinginan bagi pelajar, jadi tak boleh dianggap sebagai kebutuhan di sekolah","Batas kebutuhan/keinginan bisa bergeser saat cara hidup & tuntutan berubah — tinjau ulang secara berkala","Batas antara kebutuhan dan keinginan tetap sama walau zaman dan tuntutan sekolah berubah, selama dua dekade"],answer:1,explain:"Perubahan teknologi & tuntutan sekolah/masyarakat bisa mengubah sebuah barang dari keinginan menjadi kebutuhan (atau sebaliknya).",hint:"Apakah 'kebutuhan' seorang siswa 20 tahun lalu sama dengan sekarang?"},
{n:49,type:"mcq",micro:"Membedakan untuk keluarga",q:"Kalau kamu membantu orang tua berbelanja bulanan, membedakan kebutuhan & keinginan membantu...",options:["Membuat belanja jadi lebih lama dan membosankan tanpa manfaat bagi keluarga yang berbelanja di pasar, terutama bagi ibu","Tidak relevan untuk belanja keluarga; pembedaan itu hanya berlaku untuk uang saku pribadi anak-anak saja","Memastikan uang belanja cukup untuk pokok (beras, lauk, kebersihan) sebelum barang tambahan yang menyenangkan"],answer:2,explain:"Prinsip yang sama berlaku di tingkat keluarga: amankan pokok, lalu barang tambahan sesuai sisa.",hint:"Apa yang harus ada di keranjang lebih dulu?"},
{n:50,type:"mcq",micro:"Kualitas hidup & keinginan",q:"Menghabiskan SEDIKIT uang untuk keinginan yang benar-benar meningkatkan kualitas hidupmu (hobi yang menyehatkan, buku yang kamu nikmati)...",options:["Bisa jadi pengeluaran yang berharga — 'keinginan' tidak berarti 'tidak penting sama sekali'","Pemborosan; uang untuk keinginan tak bisa dipakai untuk kebutuhan lain di rumah","Harus dihindari mutlak oleh pelajar, dan keinginan membuat nilai sekolah menurun"],answer:0,explain:"Sebagian keinginan memberi manfaat nyata bagi kesejahteraan. Yang penting: disengaja, sesuai anggaran, & seimbang.",hint:"Apakah semua keinginan sama tidak bergunanya?"},
{n:51,type:"open",micro:"Membuat aturan pengeluaran pribadi",q:"Buat 3 aturan pribadi untuk mengelola kebutuhan & keinginan dari uang sakumu. Untuk tiap aturan, jelaskan alasannya & satu contoh penerapannya.",explain:"Aturan baik bersifat spesifik, bisa langsung dipraktikkan, & masing-masing melindungi satu hal: kebutuhan diamankan dulu, impuls dijeda, & pembelian jadi sadar.",hint:"Tiap aturan harus konkret ('sisihkan X di awal minggu') & punya alasan yang jelas.",sample:"(1) 'Sisihkan uang transport & tabungan di awal minggu, sebelum jajan apa pun.' Alasan: mencegah kehabisan uang untuk hal penting di akhir minggu. Contoh: Senin pagi, Rp30.000 (transport) & Rp20.000 (tabungan) langsung dipisah dari Rp80.000 uang saku; Rp30.000 sisanya untuk makan & keinginan. (2) 'Untuk keinginan di atas Rp25.000, tunggu 2 hari.' Alasan: memisahkan keinginan sejati dari impuls. Contoh: melihat tas Rp60.000, aku catat & cek lagi Rabu; ternyata tidak terlalu ingin, jadi tidak jadi beli. (3) 'Sebelum beli, tanya: kebutuhan atau keinginan? Kalau keinginan, apakah anggaran keinginan minggu ini masih ada?' Alasan: menjadikan pembelian keputusan sadar. Contoh: mau beli boba Rp15.000, tapi anggaran keinginan minggu ini sudah habis, jadi kutunda ke minggu depan."},
{n:52,type:"mcq",micro:"Menahan diri tanpa merasa menderita",q:"Cara mengurangi pengeluaran keinginan tanpa merasa terlalu berkorban:",options:["Tak mungkin dilakukan; keinginan tumbuh makin besar bila tak segera dipenuhi, jadi lebih baik dipenuhi","Kurangi bertahap (bukan berhenti total mendadak), ganti dengan alternatif gratis/murah, & fokus pada tujuan yang kamu tabung","Berhenti total dari semua kesenangan sekaligus mulai hari ini; tabunganmu cepat bertambah dan tidak ada godaan"],answer:1,explain:"Perubahan bertahap & mengganti dengan alternatif (main sepeda gratis, pinjam buku) lebih berkelanjutan daripada pantang mendadak.",hint:"Apa yang lebih mungkin bertahan: mengurangi sedikit demi sedikit, atau berhenti total tiba-tiba?"},
{n:53,type:"tf",micro:"Membedakan adalah keterampilan yang dilatih",q:"Benar atau Salah: Kemampuan membedakan kebutuhan & keinginan dengan jujur, & menahan impuls, berkembang dengan latihan & meninjau keputusan pengeluaranmu.",answer:true,explain:"Seperti keterampilan lain, ini menajam dengan pengulangan: mencatat pengeluaran, meninjau, & menyesuaikan aturan.",hint:"Apakah orang menjadi lebih baik mengelola uang setelah berlatih & merefleksikannya?"},
{n:54,type:"mcq",micro:"Keinginan besar sebagai tujuan bersama",q:"Kamu & saudara sama-sama ingin sebuah gim/alat yang mahal. Pendekatan yang bisa dipertimbangkan:",options:["Bertengkar sampai salah satu dari kalian menyerah; yang paling kuat berhak memakai barang itu lebih dulu","Meminta orang tua membelikan dua barang yang sama dan adil, tanpa mempertimbangkan kemampuan keuangan keluarga","Patungan & berbagi pemakaian, atau masing-masing menabung sebagian — mengubah keinginan mahal jadi tujuan yang lebih terjangkau"],answer:2,explain:"Berbagi biaya & pemakaian bisa membuat keinginan yang di luar jangkauan satu orang menjadi mungkin.",hint:"Apakah keinginan mahal harus selalu ditanggung & dimiliki satu orang?"},
{n:55,type:"mcq",micro:"Menilai 'diskon' pada keinginan",q:"Sebuah keinginan yang tadinya tidak kamu rencanakan sedang 'diskon 50%'. Sikap yang tepat:",options:["Diskon tidak mengubah apakah kamu membutuhkannya; kalau tidak masuk anggaran keinginan & tidak benar-benar kamu inginkan, melewatkannya bukan 'kerugian'","Wajib membeli; diskon 50% adalah kesempatan langka, dan barang itu akan berguna kelak di kemudian hari, walau belum direncanakan","Diskon berarti kamu menghemat uang, jadi membeli barang yang sedang diskon merupakan keputusan bijak pada akhirnya, tanpa perlu menimbang kebutuhan"],answer:0,explain:"Membeli sesuatu yang tidak kamu butuhkan/inginkan karena diskon berarti mengeluarkan uang, bukan menghemat.",hint:"Uangmu bertambah atau berkurang setelah membeli barang 'diskon' yang tidak direncanakan?"},
{n:56,type:"mcq",micro:"Kebutuhan tersembunyi di balik keinginan",q:"Kamu sangat ingin gawai/pakaian baru. Kadang di baliknya ada kebutuhan yang belum terpenuhi, seperti...",options:["Murni kebutuhan materi, jadi cara memenuhinya hanyalah dengan membeli barang baru itu, tanpa alternatif lain","Ingin diterima teman, ingin merasa mampu, atau bosan — yang bisa dipenuhi dengan cara lain yang tidak menghabiskan uang","Tak ada apa-apa di balik keinginan itu; keinginan membeli barang tak berkaitan dengan perasaan, hanya soal harga dan promo toko"],answer:1,explain:"Mengenali 'kebutuhan emosional' di balik keinginan membeli membantu menanganinya tanpa selalu berbelanja.",hint:"Apa perasaan yang kamu harap berubah setelah membeli barang itu?"},
{n:57,type:"tf",micro:"Anggaran fleksibel, bukan hukuman",q:"Benar atau Salah: Anggaran pada dasarnya adalah daftar larangan yang membuat hidup terasa berat, bukan alat untuk membantumu mencapai tujuan & menikmati uang dengan tenang.",answer:false,explain:"Anggaran yang membedakan kebutuhan, tabungan, & keinginan sebaiknya dilihat sebagai 'izin untuk membelanjakan dengan sengaja' — alat untuk mencapai tujuan & menikmati uang dengan tenang, bukan hukuman.",hint:"Apakah anggaran itu 'kamu tidak boleh' atau 'inilah rencanamu untuk memakai uangmu'?"},
{n:58,type:"mcq",micro:"Konsisten di tekanan",q:"Di toko, temanmu mendesak 'ayo beli, nanti kehabisan!' untuk sebuah keinginan yang tidak kamu rencanakan. Respons:",options:["Beli dan jangan menyesal nanti; barang yang kamu inginkan mungkin segera habis","Pinjam uang temanmu untuk membeli barang itu saat ini juga di toko","Tarik napas, ingat anggaran & tujuanmu, & katakan kamu akan memikirkannya dulu"],answer:2,explain:"Keputusan uang yang baik jarang perlu diambil dalam hitungan detik. Jeda memisahkan dorongan dari kebutuhan nyata.",hint:"Apa yang biasanya kamu rasakan sehari setelah membeli karena panik?"},
{n:59,type:"mcq",micro:"Meninjau kategori secara berkala",q:"Meninjau ulang 'apa yang kuanggap kebutuhan & keinginan' setiap beberapa bulan berguna karena...",options:["Keadaan berubah (sekolah, kegiatan, harga); sebuah barang bisa berpindah kategori & anggaranmu perlu menyesuaikan","Kategori kebutuhan dan keinginan tak berubah, dan meninjaunya kembali adalah pekerjaan sia-sia, walau tuntutan sekolah berganti","Meninjau ulang hanya membuang waktu; anggaran yang sudah dibuat sekali tidak perlu disesuaikan lagi nanti"],answer:0,explain:"Literasi keuangan mencakup memperbarui rencana saat hidup berubah, bukan mengikuti daftar lama secara buta.",hint:"Apakah kebutuhanmu semester ini sama persis dengan semester lalu?"},
{n:60,type:"open",micro:"Menganalisis keputusan pengeluaran",q:"Seorang teman berkata: 'Aku selalu kehabisan uang saku sebelum akhir minggu, jadi sering pinjam untuk ongkos pulang. Tapi aku juga sering beli minuman kekinian & top up gim di awal minggu.' Analisis: (1) apa masalah pengelolaannya, (2) kebutuhan mana yang tidak diamankan, (3) keinginan mana yang bisa dikurangi, (4) rencana konkret untuk memperbaikinya.",explain:"Jawaban baik mengenali urutan yang salah (keinginan sebelum kebutuhan → berutang), menunjuk kebutuhan yang tidak diamankan (ongkos), memilih keinginan spesifik untuk dikurangi, & memberi rencana 'amankan kebutuhan & tabungan di awal, batasi keinginan, jangan berutang untuk hal yang bisa dianggarkan'.",hint:"Masalah intinya bukan 'terlalu boros', tapi 'urutan salah' — keinginan dibayar sebelum kebutuhan.",sample:"(1) Masalah: ia membelanjakan keinginan (minuman, top up) di awal minggu sebelum mengamankan kebutuhan (ongkos), lalu terpaksa berutang untuk kebutuhan — utang untuk kebutuhan yang seharusnya bisa dianggarkan. (2) Kebutuhan yang tidak diamankan: ongkos transport pulang setiap hari. (3) Keinginan yang bisa dikurangi: minuman kekinian (bisa dikurangi jadi 1–2x seminggu atau bawa minum sendiri), top up gim (dijeda atau dibatasi jumlah tertentu per bulan). (4) Rencana: di awal minggu, langsung pisahkan uang ongkos untuk 5–6 hari ke amplop/dompet terpisah sebelum apa pun; sisihkan sedikit tabungan; sisanya baru untuk makan & keinginan dengan batas harian (mis. maksimal Rp10.000/hari untuk jajan tambahan). Kalau uang keinginan habis, tunggu minggu depan — jangan pinjam. Catat pengeluaran seminggu untuk melihat ke mana perginya uang."},
{n:61,type:"mcq",micro:"Jebakan 'aku pantas mendapatkannya'",q:"Pikiran 'aku sudah kerja keras, aku pantas membeli ini' untuk keinginan mahal yang tidak direncanakan...",options:["Berarti kamu harus membeli apa yang kamu mau; kerja kerasmu menghapus semua batas anggaran demi menghargai diri","Bisa jadi pembenaran yang mengabaikan anggaran & tujuan; menghargai diri boleh, tapi dengan hadiah yang terjangkau & terencana","Menjadi alasan yang sah dan bijak, jadi tak perlu ditimbang dengan kebutuhan atau tujuan menabungmu, walau tabungan menipis"],answer:1,explain:"'Aku pantas' sering dipakai untuk membenarkan pengeluaran impulsif. Hadiah untuk diri lebih baik direncanakan & sesuai kemampuan.",hint:"Apakah 'aku pantas' berarti 'anggaran & tujuan tidak berlaku kali ini'?"},
{n:62,type:"tf",micro:"Membeli sesuatu jarang mengubah perasaan lama",q:"Benar atau Salah: Membeli barang baru sering memberi rasa senang sesaat, tapi jarang menyelesaikan masalah yang lebih dalam (bosan, ingin diterima, stres) — perasaan itu biasanya kembali.",answer:true,explain:"'Belanja untuk memperbaiki perasaan' cenderung jadi siklus. Menangani akar masalah (aktivitas, hubungan, istirahat) lebih tahan lama.",hint:"Berapa lama rasa senang dari sebuah pembelian biasanya bertahan?"},
{n:63,type:"mcq",micro:"Keinginan & perbandingan sosial",q:"Melihat orang lain (di sekolah atau media sosial) dengan banyak barang bagus bisa membuatmu merasa 'kurang'. Yang perlu diingat:",options:["Mereka jauh lebih bahagia daripada kamu dengan banyak barang bagus; perasaanmu memang benar adanya, dan kamu tertinggal dalam banyak hal sehari-hari","Kamu harus segera mengejar mereka dengan membeli barang yang sama agar setara, walau harus meminjam uang atau menunda kebutuhan lain; ketinggalan itu tidak nyaman","Kamu melihat sisi yang mereka tampilkan, bukan keadaan keuangan mereka sebenarnya (mungkin berutang, dibelikan, atau hanya untuk konten); membandingkan pengeluaran jarang adil atau berguna"],answer:2,explain:"Perbandingan sosial mendorong pengeluaran yang tidak sesuai kemampuan & nilaimu. Yang terlihat bukan gambaran penuh.",hint:"Apakah kamu tahu bagaimana orang itu membayar semua barangnya?"},
{n:64,type:"mcq",micro:"Keinginan yang tumbuh tanpa batas",q:"Setelah membeli sesuatu yang diinginkan, sering muncul keinginan baru yang lebih besar. Ini disebut...",options:["'Roda kepuasan' — standar kita naik, & kepuasan dari pembelian memudar; menyadarinya membantu tidak terus mengejar","Tanda bahwa kamu harus terus membeli barang baru; kepuasan hanya datang dari pembelian yang makin besar","Hal yang tak terjadi pada siapa saja; orang tetap puas lama setelah membeli yang diinginkan, jadi tak perlu dipikirkan"],answer:0,explain:"Keinginan cenderung meluas mengikuti apa yang kita miliki. Kepuasan berkelanjutan lebih datang dari tujuan, hubungan, & pengalaman daripada barang berikutnya.",hint:"Apakah membeli hal yang kamu inginkan tahun lalu membuatmu berhenti menginginkan hal baru?"},
{n:65,type:"tf",micro:"Nilai orang tidak ditentukan barangnya",q:"Benar atau Salah: Nilai & harga diri seseorang ditentukan oleh merek & jumlah barang yang mereka miliki.",answer:false,explain:"Nilai & harga diri seseorang TIDAK ditentukan oleh kepemilikan barang. Menautkan harga diri pada barang membuat kita rentan pada tekanan pengeluaran & tidak pernah merasa cukup.",hint:"Apakah temanmu yang baik menjadi kurang berharga kalau sepatunya biasa saja?"},
{n:66,type:"mcq",micro:"Menyeimbangkan hemat & pelit",q:"Perbedaan antara 'hemat' & 'pelit':",options:["Hemat berarti tak membeli apa-apa, sedangkan pelit berarti membeli sedikit saja untuk diri sendiri dan keluarga, dan keduanya ditentukan oleh jumlah uang yang dimiliki","Hemat = membelanjakan dengan sadar pada hal yang berarti & memangkas yang tidak; pelit = menolak pengeluaran yang wajar/perlu (termasuk untuk orang lain) sampai merugikan hubungan atau kesehatan","Tidak ada bedanya; orang hemat maupun pelit sama-sama mengurangi pengeluaran sebanyak mungkin agar uangnya aman, jadi dua sebutan itu bisa dipakai bergantian dalam kehidupan sehari-hari"],answer:1,explain:"Tujuannya bukan mengeluarkan uang sesedikit mungkin, tapi mengeluarkannya dengan bijak — termasuk untuk kebutuhan & sesekali kesenangan & orang lain.",hint:"Apakah menolak membelikan hadiah kecil untuk teman dekat yang berulang tahun itu 'hemat'?"},
{n:67,type:"mcq",micro:"Keinginan vs kebutuhan dalam kelompok",q:"Kelompokmu mengumpulkan dana. Sebagian ingin memakainya untuk dekorasi mewah (keinginan), sebagian untuk hal fungsional yang diperlukan acara (kebutuhan). Pendekatan:",options:["Prioritaskan dekorasi mewah lebih dulu agar acara terlihat bagus, lalu kebutuhan fungsional dipikirkan bila uangnya masih tersisa","Habiskan semua dana untuk salah satu pilihan tanpa berdiskusi, supaya keputusannya cepat dan tidak ada perdebatan panjang","Amankan dulu yang diperlukan agar acara berjalan, lalu pakai sisa untuk hal 'nilai tambah' yang disepakati"],answer:2,explain:"Prinsip 'kebutuhan dulu, keinginan dari sisa' berlaku juga untuk keuangan kelompok.",hint:"Apa yang membuat acara bisa berjalan vs apa yang hanya mempercantik?"},
{n:68,type:"tf",micro:"Kebutuhan bisa dipenuhi dengan standar berbeda",q:"Benar atau Salah: Memenuhi sebuah kebutuhan tidak berarti harus dengan versi termewah — makan bergizi bisa dari masakan rumah sederhana, & pakaian layak tidak harus bermerek.",answer:true,explain:"Kebutuhan punya tingkat pemenuhan yang beragam. Memilih tingkat yang cukup & terjangkau tetap memenuhi kebutuhan, & menyisakan uang untuk hal lain.",hint:"Apakah 'makan bergizi' harus berarti restoran mahal?"},
{n:69,type:"mcq",micro:"Keinginan yang menghasilkan (batas)",q:"'Aku ingin membeli alat mahal karena bisa untuk menghasilkan uang.' Sebelum menyetujui logika ini pada diri sendiri:",options:["Periksa jujur: apakah aku punya rencana nyata & realistis untuk menghasilkan dengannya, atau ini hanya pembenaran untuk keinginan?","Logika 'bisa menghasilkan uang' membenarkan pembelian apa saja, jadi tak perlu diperiksa lagi sebelum membeli alatnya, asal alatnya populer","Alat mahal menghasilkan uang lebih besar daripada harganya, jadi membelinya tak akan pernah rugi, terutama bagi pemula"],answer:0,explain:"'Investasi untuk menghasilkan' adalah alasan sah HANYA bila ada rencana konkret. Sering ia dipakai untuk membenarkan keinginan.",hint:"Apakah aku benar-benar akan memakainya untuk menghasilkan, atau aku hanya menginginkannya?"},
{n:70,type:"order",micro:"Menghadapi dorongan membeli yang kuat",q:"Kamu merasa dorongan kuat untuk membeli sebuah keinginan yang tidak direncanakan. Urutkan langkah menahannya.",items:["Berhenti & namai perasaannya: 'aku sedang sangat ingin ini karena ...'","Tunda keputusan: 'aku akan pikirkan lagi besok/2 hari'","Cek: apakah kebutuhan & tabungan sudah aman & apakah masuk anggaran keinginan","Kalau setelah jeda masih ingin & masuk anggaran → beli dengan tenang; kalau tidak → lepaskan"],answer:[0,1,2,3],explain:"Namai perasaan → tunda → cek anggaran → putuskan setelah dorongan mereda.",hint:"Dorongan paling kuat di awal; jeda membuatnya mereda."},
{n:71,type:"mcq",micro:"Keinginan langganan (subscription)",q:"Layanan berlangganan (musik, gim, aplikasi) berbahaya bagi anggaran karena...",options:["Tak membebani; nilainya kecil dibanding uang saku bulanan seorang pelajar yang diberi orang tua","Biaya kecil bulanan mudah terlupa & menumpuk; tinjau berkala mana yang benar-benar kamu pakai & batalkan yang tidak","Gratis; layanan langganan hanya menarik biaya bila kita aktif memakainya setiap bulan penuh di aplikasi"],answer:1,explain:"Langganan yang tidak dipakai adalah 'kebocoran' uang yang tak terasa. Meninjaunya tiap beberapa bulan menutup kebocoran itu.",hint:"Berapa layanan berlangganan yang kamu bayar tapi jarang pakai?"},
{n:72,type:"mcq",micro:"Menghargai apa yang sudah dimiliki",q:"Kebiasaan yang mengurangi dorongan membeli keinginan baru:",options:["Terus membandingkan barang milikmu dengan produk terbaru dan teman yang punya model paling baru tiap bulan di kelas","Menganggap semua barang yang sudah kamu punya sudah usang dan tidak layak dipakai lagi, meski sebenarnya masih bagus dan berfungsi baik","Sesekali memperhatikan & mensyukuri barang yang sudah kamu punya & berfungsi baik — 'aku sudah punya cukup untuk ini'"],answer:2,explain:"Rasa 'cukup' mengurangi tekanan untuk terus membeli. Ini keterampilan yang bisa dilatih.",hint:"Apakah barang yang sudah kamu punya masih memenuhi kebutuhan/keinginannya dengan baik?"},
{n:73,type:"tf",micro:"Tidak ada rasio 'benar' untuk semua orang",q:"Benar atau Salah: Berapa persen uang yang sebaiknya untuk kebutuhan, tabungan, keinginan, & berbagi bisa berbeda antar orang tergantung penghasilan, tanggungan, & tujuan.",answer:true,explain:"Panduan seperti 50/30/20 hanyalah titik awal. Anak dengan uang saku Rp20.000 & Rp200.000 punya keadaan berbeda.",hint:"Apakah anak yang harus membantu biaya keluarga punya proporsi yang sama dengan yang tidak?"},
{n:74,type:"mcq",micro:"Keinginan & hadiah dari orang lain",q:"Kalau seseorang menawarkan membelikan keinginanmu yang mahal, pertimbangan yang bijak:",options:["Terima kasih & pertimbangkan apakah itu wajar (bukan menimbulkan kewajiban yang tidak nyaman); barang gratis pun 'berbiaya' bila menciptakan utang budi atau kebiasaan bergantung","Terima apa saja yang gratis dari siapa saja tanpa berpikir; barang gratis tak membawa konsekuensi, dan itu tanda orang yang pandai berhemat setiap saat","Tolak semua pemberian dari orang mana pun; menerima hadiah dalam bentuk apa saja hanya merepotkan dirimu, dan menjaga harga diri di depan keluarga"],answer:0,explain:"Bahkan pemberian bisa punya 'harga' sosial. Menilai konteksnya adalah bagian dari pengelolaan yang matang.",hint:"Apakah 'gratis' selalu berarti 'tanpa konsekuensi'?"},
{n:75,type:"mcq",micro:"Keinginan sebagai bagian identitas",q:"Hobi atau minat (musik, olahraga, seni) yang kamu belanjakan uangnya...",options:["Harus dihentikan demi menabung; semua hobi hanya menghabiskan uang saku dan waktu belajar yang seharusnya dipakai lebih baik","Bisa jadi bagian penting dari siapa dirimu & layak dianggarkan secara sadar — 'keinginan' tidak berarti 'tanpa nilai bagi hidupmu'","Pemborosan; hobi tak memberi hasil nyata, jadi uangnya lebih baik dialihkan ke tabungan seluruhnya setiap bulan"],answer:1,explain:"Pengeluaran berbasis nilai berarti mengalokasikan uang ke hal yang benar-benar berarti bagimu — sambil tetap dalam batas & mengamankan kebutuhan.",hint:"Apakah semua 'keinginan' sama tidak pentingnya bagi kehidupan seseorang?"},
{n:76,type:"tf",micro:"Iklan & 'kebutuhan' buatan",q:"Benar atau Salah: Pemasaran bersikap netral & tidak pernah berusaha membuat sebuah keinginan terasa seperti kebutuhan yang wajib dipenuhi.",answer:false,explain:"Iklan yang efektif justru sering membuat produk terasa esensial ('kamu perlu ini agar diterima / sukses / bahagia'). Menyadari taktik ini & bertanya 'apakah aku benar-benar akan bermasalah tanpa ini?' membantu berpikir jernih.",hint:"Apa yang iklan buat kamu takutkan akan terjadi tanpa produknya?"},
{n:77,type:"mcq",micro:"Menyeimbangkan masa kini & masa depan",q:"Sikap sehat terhadap kebutuhan, keinginan, & tabungan:",options:["Habiskan semuanya sekarang untuk bersenang-senang, sedangkan masa depan dan tabungan adalah urusan nanti saja, dan kamu baru memikirkannya ketika benar-benar butuh nanti","Tabung semua uangmu tanpa pengecualian dan jangan menikmati hal menyenangkan; kesenangan hanya membuatmu boros tiap saat, lalu hidup hemat sampai tua","Penuhi kebutuhan hari ini, nikmati sebagian keinginan (dalam batas), & bangun tabungan untuk keamanan & tujuan masa depan — ketiganya, bukan mengorbankan satu sepenuhnya"],answer:2,explain:"Ekstrem mana pun (hanya sekarang / hanya nanti) tidak berkelanjutan. Keseimbangan yang disengaja adalah tujuannya.",hint:"Apakah kamu harus memilih antara 'hidup sekarang' & 'aman nanti'?"},
{n:78,type:"mcq",micro:"Membedakan untuk keputusan besar",q:"Untuk pembelian besar (gawai, sepeda, alat), memisahkan 'bagian yang kebutuhan' & 'bagian yang keinginan' membantu...",options:["Mis. butuh 'ponsel yang bisa untuk tugas & komunikasi' (kebutuhan) tapi ingin 'model termahal dengan fitur kamera pro' (keinginan) — kamu bisa memilih yang memenuhi kebutuhan dengan harga wajar","Tidak membantu; semua bagian dari satu barang sama-sama kebutuhan dan harus dibeli sekaligus tanpa dipisah, jadi pemisahan hanya membuang waktu saat berbelanja barang elektronik","Membuat semua pembelian besar menjadi kebutuhan, dan kamu bebas membeli versi termahal dengan alasan memerlukannya; itu sudah cukup bagi penjual dan keluarga"],answer:0,explain:"Banyak pembelian adalah campuran. Mengenali bagian kebutuhan (fungsi minimum) vs keinginan (kelebihan) memandu pilihan yang hemat.",hint:"Apa fungsi minimum yang benar-benar kamu perlukan, & apa 'tambahannya' yang kamu inginkan?"},
{n:79,type:"mcq",micro:"Ketika keinginan menang sesekali",q:"Kamu membuat rencana lalu sesekali membeli keinginan di luar rencana. Sikap yang produktif:",options:["Menghukum diri sendiri dengan keras setiap kali menyimpang dan memotong seluruh uang jajan minggu berikutnya sebagai balasannya","Akui, catat, & lihat apakah polanya sering; sesekali menyimpang itu manusiawi — yang penting rata-rata & kebiasaan keseluruhan tetap sehat","Menyerah pada seluruh rencana setelah gagal sekali, lalu berbelanja tanpa catatan dan batas lagi seperti dulu"],answer:1,explain:"Kesempurnaan bukan tujuan. Pola jangka panjang & kemampuan kembali ke jalur lebih penting daripada satu penyimpangan.",hint:"Apakah satu kali menyimpang berarti seluruh rencana gagal?"},
{n:80,type:"open",micro:"Menganalisis pengaruh sosial pada keinginan",q:"Sebuah tren membuat banyak siswa di sekolahmu merasa 'harus punya' sebuah barang tertentu (sepatu/tas/gawai model tertentu). Analisis: (1) mengapa keinginan ini terasa seperti kebutuhan, (2) apa risikonya bagi siswa yang keluarganya kurang mampu, (3) bagaimana kamu memutuskan apakah akan ikut membeli, (4) satu cara sikap ini bisa lebih sehat di lingkunganmu.",explain:"Jawaban baik mengenali mekanisme sosial (takut berbeda, normalisasi, pemasaran), dampak nyata pada yang kurang mampu (utang, memangkas kebutuhan, malu), kerangka keputusan pribadi (ingin sejati? masuk anggaran? alternatif?), & solusi budaya (tidak mengejek, menghargai hal non-materi).",hint:"Pikirkan: apa yang membuat keinginan ini menular, & siapa yang paling terluka olehnya?",sample:"(1) Terasa seperti kebutuhan karena: takut dikucilkan/berbeda; melihat banyak teman & konten menampilkannya sehingga terasa 'normal' & 'wajib'; pemasaran yang mengaitkan barang itu dengan penerimaan sosial. (2) Risiko bagi yang kurang mampu: tekanan untuk membeli sesuatu di luar kemampuan bisa membuat orang tua berutang atau memangkas kebutuhan lain; siswa bisa merasa malu, rendah diri, atau terkucil — kerugian emosional & finansial. (3) Cara memutuskan: tanya apakah aku benar-benar menginginkannya untuk diriku (bukan hanya takut berbeda); apakah masuk anggaranku tanpa mengorbankan kebutuhan/tabungan; apakah versi lebih murah/bekas bisa; kalau tidak masuk, lewati & sadari bahwa nilaiku tidak ditentukan barang ini. (4) Sikap lebih sehat: menormalkan bahwa orang punya kemampuan berbeda & itu bukan aib; tidak menilai atau mengejek barang teman; guru/OSIS bisa mendorong budaya di mana kontribusi, karakter, & keterampilan lebih dihargai daripada kepemilikan barang."},
{n:81,type:"mcq",micro:"Kerangka keputusan pembelian",q:"Kerangka singkat sebelum membeli apa pun yang tidak sepele:",options:["Apakah barang itu terlihat keren? Apakah sedang diskon? Apakah temanku sudah punya? Apakah penjualnya terlihat ramah dan meyakinkan? setiap saat","Apakah aku punya cukup uang di dompet sekarang? Kalau ada, langsung saja beli sebelum barangnya habis atau diambil orang lain","Kebutuhan atau keinginan? Sudahkah kebutuhan & tabungan bulan ini aman? Masuk anggaran keinginan? Apakah aku masih menginginkannya setelah jeda? Apa biaya peluangnya?"],answer:2,explain:"Kerangka ini menyaring pembelian impulsif & memastikan yang penting tetap terlindungi.",hint:"Gabungkan: jenis + kebutuhan aman? + anggaran? + jeda + biaya peluang."},
{n:82,type:"mcq",micro:"Menyusun anggaran sederhana",q:"Uang saku Rp60.000/minggu. Contoh pembagian yang masuk akal untuk seorang siswa:",options:["Kebutuhan (transport + makan) ~Rp33.000; tabungan ~Rp12.000; keinginan ~Rp10.000; berbagi/cadangan ~Rp5.000","Keinginan Rp50.000 setiap minggu; sisanya Rp10.000 dibagi untuk transport, makan, dan tabungan, yang penting bersenang-senang dulu","Semua Rp60.000 dipakai untuk keinginan minggu itu; kebutuhan makan dan transport bisa dimintakan lagi kepada orang tua"],answer:0,explain:"Angka pastinya bergantung keadaan, tapi polanya: kebutuhan & tabungan diamankan dulu, keinginan & berbagi dari sisa.",hint:"Bagian mana yang harus ditetapkan lebih dulu?"},
{n:83,type:"tf",micro:"Membedakan mendukung tujuan besar",q:"Benar atau Salah: Membedakan kebutuhan & keinginan hanya berguna bagi orang berpenghasilan rendah; begitu penghasilan cukup besar, kebiasaan ini tidak lagi penting untuk mencapai tujuan keuangan.",answer:false,explain:"Kebiasaan ini membantu pada tingkat penghasilan berapa pun. 'Belanjakan lebih sedikit dari yang dihasilkan, sisihkan selisihnya' mendasari hampir semua nasihat keuangan yang baik, & membedakan kebutuhan/keinginan adalah cara praktis menjalankannya.",hint:"Apa kebiasaan yang mendasari hampir semua nasihat keuangan yang baik?"},
{n:84,type:"mcq",micro:"Keinginan yang benar-benar layak",q:"Sebuah keinginan lebih layak dibeli (dalam anggaran) bila...",options:["Sedang tren di kalangan teman sebaya, dan banyak yang sudah membeli; kamu tak boleh ketinggalan zaman lagi","Kamu masih menginginkannya setelah jeda, akan menikmatinya lama, sesuai nilai/minatmu, & tidak mengorbankan kebutuhan atau tujuan penting","Harganya tinggi, jadi berkualitas bagus dan layak dibeli walau harus menabung lama sekali dan menunda kebutuhan lain"],answer:1,explain:"Keinginan yang 'tahan uji jeda', memberi nilai lama, & sesuai dirimu adalah pengeluaran yang lebih bijak.",hint:"Apakah kamu akan senang memilikinya sebulan dari sekarang?"},
{n:85,type:"order",micro:"Merencanakan pembelian keinginan besar",q:"Kamu ingin sebuah barang seharga Rp500.000 (keinginan, bukan mendesak). Urutkan langkah.",items:["Pastikan kebutuhan bulanan & dana darurat kecil sudah aman","Tetapkan jumlah tabungan mingguan untuk tujuan ini (mis. Rp50.000)","Hitung waktu (Rp500.000 ÷ Rp50.000 = 10 minggu) & apa yang kamu kurangi untuk itu","Tabung konsisten; setelah tercapai, beli dengan tenang tanpa rasa bersalah"],answer:[0,1,2,3],explain:"Amankan kebutuhan & darurat → tetapkan tabungan tujuan → hitung waktu & biaya peluang → tabung & beli.",hint:"Keinginan besar didanai lewat tabungan tujuan, bukan utang atau mengorbankan kebutuhan."},
{n:86,type:"mcq",micro:"Mengajari adik/teman",q:"Cara terbaik membantu adik memahami kebutuhan vs keinginan:",options:["Menyuruhnya menghafal definisi kebutuhan dan keinginan dari buku sampai lancar tanpa berlatih memilih langsung setiap hari","Melarangnya membeli apa-apa sampai dewasa; ia tak salah memilih dan tidak boros nantinya, itu cara paling aman dan adil baginya","Contohkan dengan situasi nyata ('kita punya Rp20.000, ada beras habis & ada permen — mana dulu?') & biarkan ia berlatih memilih"],answer:2,explain:"Belajar lewat contoh & latihan pengambilan keputusan lebih menempel daripada definisi.",hint:"Bagaimana anak belajar paling baik — menghafal, atau berlatih memutuskan?"},
{n:87,type:"tf",micro:"Kebutuhan & keinginan berlaku untuk waktu & perhatian juga",q:"Benar atau Salah: Prinsip membedakan 'yang penting/perlu' dari 'yang menyenangkan tapi bisa ditunda' juga berguna untuk mengelola waktu & perhatian, bukan hanya uang.",answer:true,explain:"Sama seperti uang, waktu terbatas: mengamankan yang penting (belajar, tidur, kesehatan) sebelum yang menyenangkan (hiburan) adalah pola yang sama.",hint:"Apakah 'kebutuhan dulu, keinginan kemudian' hanya berlaku untuk uang?"},
{n:88,type:"mcq",micro:"Menghindari dua ekstrem",q:"Dua sikap yang tidak sehat terhadap keinginan:",options:["(a) Menuruti setiap keinginan (boros, berutang, tujuan tak tercapai) & (b) menolak semua kesenangan (tidak berkelanjutan, hidup terasa berat) — keduanya keliru; keseimbangan yang disengaja lebih baik","Kedua sikap itu sama-sama sehat dan bisa dipilih sesuka hati; tak ada akibat jangka panjang dari keduanya, jadi tak perlu ada keseimbangan yang disengaja ataupun dievaluasi oleh keluarga dan guru","Hanya sikap (a) yang bermasalah, sedangkan menolak semua kesenangan adalah cara paling benar mengelola uang, tanpa dicek lagi bagi pelajar maupun orang dewasa mana pun dan keluarga"],answer:0,explain:"Tujuannya bukan pantang total atau menuruti semua, melainkan pengeluaran yang disengaja & seimbang.",hint:"Antara 'beli semua' & 'jangan pernah menikmati apa pun', di mana posisi yang bisa bertahan?"},
{n:89,type:"mcq",micro:"Refleksi berkala",q:"Sebulan sekali meninjau: 'Apakah kebutuhanku terpenuhi? Apakah aku menabung sesuai rencana? Apakah pengeluaran keinginanku terasa sepadan?' berguna untuk...",options:["Tidak ada gunanya; pola pengeluaran bulan lalu tak berpengaruh pada bulan ini","Belajar dari pola nyata & menyesuaikan aturan/anggaran bulan berikutnya","Menghukum diri sendiri atas pengeluaran bulan lalu yang tak sesuai rencana"],answer:1,explain:"Anggaran & aturan adalah alat yang diperbaiki terus berdasarkan pengalaman, bukan aturan sekali jadi.",hint:"Bagaimana rencana bulan depan bisa lebih baik?"},
{n:90,type:"mcq",micro:"Menutup: kebutuhan vs keinginan",q:"Sikap paling berguna:",options:["Beli apa saja yang kamu inginkan selagi uang masih ada di tangan; tabungan dan kebutuhan bisa dipikirkan akhir bulan, tanpa jeda walau keadaan dan tujuan tiap orang berbeda, dan semua pembelian dianggap sama penting","Jangan membeli apa-apa untuk kesenangan, simpan semua uang untuk masa depan, abaikan iklan, dan jangan meninjau kebiasaan belanjamu lagi; semua keinginan merugikan dan menghambat tujuanmu jangka panjang di sekolah","Amankan kebutuhan & tabungan lebih dulu; akui keinginan itu sah tapi bisa ditunda; beri jeda sebelum membeli; belanjakan pada hal yang berarti; tinjau polamu berkala — bukan menuruti semua atau menolak semua"],answer:2,explain:"Inti: kebutuhan & tabungan diamankan; keinginan dikelola dengan jeda, batas, & berbasis nilai; pola ditinjau.",hint:"Gabungkan: amankan kebutuhan & tabungan + keinginan dikelola (jeda, batas, nilai) + tinjau."},
{n:91,type:"mcq",micro:"Ringkasan: kebutuhan vs keinginan",q:"Rangkuman paling tepat:",options:["Kebutuhan menopang hidup & sekolah; keinginan menambah senang tapi bisa ditunda; kebutuhan & tabungan diamankan lebih dulu, keinginan dikelola (jeda, batas anggaran), waspada iklan & tekanan teman, dan pola ditinjau berkala","Semua pengeluaran sama pentingnya dan tak perlu dipilah; yang penting dipakai untuk hal yang kamu suka, iklan dan teman tak memengaruhi, tabungan dipikirkan hanya bila sisa, dan pola belanja tak perlu ditinjau","Keinginan harus dilarang sepenuhnya, hanya kebutuhan yang boleh dibeli; tabungan tak perlu dipikirkan dan uang akan cukup sendiri, pola tak perlu ditinjau, dan iklan atau tekanan teman sebaiknya dituruti saja"],answer:0,explain:"Kebutuhan vs keinginan + konteks + kebutuhan & tabungan dulu + keinginan dikelola + waspada iklan & tekanan sosial + tinjau berkala.",hint:"Gabungkan definisi + konteks + urutan prioritas + pengelolaan keinginan + kewaspadaan + tinjauan."},
{n:92,type:"tf",micro:"Ini keterampilan yang bisa dilatih",q:"Benar atau Salah: Membedakan kebutuhan & keinginan dengan jujur & menahan impuls adalah bakat bawaan — kamu memilikinya atau tidak, & latihan atau refleksi tidak mengubahnya.",answer:false,explain:"Ini keterampilan, bukan bakat. Ia menguat dengan latihan, pencatatan, & refleksi — setiap keputusan pengeluaran yang kamu buat sadar & tinjau menajamkannya.",hint:"Apakah orang menjadi lebih baik mengelola uang setelah berlatih?"},
{n:93,type:"mcq",micro:"Tiga prinsip praktis",q:"Tiga prinsip praktis mengelola kebutuhan & keinginan:",options:["Larang semua kesenangan; jangan membeli yang tak mutlak diperlukan; dan jangan percaya pada orang yang menawarkan hiburan, sebagaimana biasanya di sekolah dan di rumah","Amankan kebutuhan & tabungan di awal (bukan sisa); jeda sebelum keinginan yang tidak sepele; & belanjakan pada hal yang benar-benar berarti bagimu sambil waspada pada iklan & tekanan sosial","Turuti semua keinginan lebih dulu; abaikan tabungan sampai akhir bulan; dan ikuti tren yang ramai di media sosial setiap saat, dan itu membuatmu diterima banyak teman"],answer:1,explain:"Amankan kebutuhan & tabungan dulu + jeda sebelum keinginan + belanja berbasis nilai & waspada pengaruh = inti.",hint:"Gabungkan: amankan dulu + jeda + berbasis nilai."},
{n:94,type:"open",micro:"Kapstone: rencana pengeluaran pribadi 3 bulan",q:"Buat rencana pengeluaran pribadi 3 bulan. Sertakan: (1) perkiraan total pemasukan (uang saku + lainnya), (2) daftar kebutuhan tetap bulananmu + biayanya, (3) jumlah tabungan yang disisihkan di awal & untuk apa, (4) anggaran keinginan (jumlah & batas), (5) satu keinginan besar yang ingin kamu capai + rencana menabungnya, (6) 2 aturan pribadi untuk menahan pembelian impulsif, (7) bagaimana kamu akan meninjau di akhir tiap bulan.",explain:"Kapstone menggabungkan semuanya: menghitung pemasukan, mengamankan kebutuhan & tabungan lebih dulu, menganggarkan keinginan dengan batas, menetapkan tujuan besar dengan rencana menabung, membuat aturan menahan impuls, & menjadwalkan tinjauan berkala.",hint:"Pastikan total (kebutuhan + tabungan + keinginan + cadangan) tidak melebihi pemasukan, & tabungan disisihkan SEBELUM keinginan.",sample:"Contoh: (1) Pemasukan: uang saku Rp60.000/minggu ≈ Rp240.000/bulan + bantu paman Rp80.000/bulan = Rp320.000/bulan; 3 bulan ≈ Rp960.000. (2) Kebutuhan tetap/bulan: transport Rp90.000, makan siang Rp90.000, alat tulis/keperluan sekolah Rp30.000 = Rp210.000. (3) Tabungan disisihkan di awal: Rp70.000/bulan — Rp40.000 dana darurat kecil, Rp30.000 untuk tujuan besar (lihat 5). (4) Anggaran keinginan: Rp30.000/bulan, batas Rp10.000/minggu untuk jajan tambahan/hiburan; sisa Rp10.000/bulan cadangan tak terduga. (5) Keinginan besar: sepatu lari Rp270.000; dengan Rp30.000/bulan dari tabungan tujuan + kalau ada uang lebih, ~3 bulan tercapai (atau kupercepat dengan menambah dari cadangan bila utuh). (6) Aturan: (a) 'Sisihkan transport, makan, & tabungan di awal minggu sebelum jajan apa pun.' (b) 'Untuk keinginan di atas Rp25.000, tunggu 2 hari & cek anggaran keinginan.' (7) Tinjauan: setiap akhir bulan, bandingkan pengeluaran nyata (dari catatan harian di ponsel) dengan rencana; tandai pos yang meleset & cari sebabnya; sesuaikan anggaran bulan berikutnya."},
{n:95,type:"mcq",micro:"Menilai sebuah anggaran teman",q:"Teman menunjukkan anggaran: 70% keinginan, 25% kebutuhan, 5% tabungan, & ia sering pinjam untuk transport. Masalah utamanya:",options:["Tidak ada masalah; proporsi pengeluaran bebas dipilih sesuai selera masing-masing, dan tabungan bisa disusun belakangan setelah semua keinginan terpenuhi","Tabungan terlalu besar, dan kesenangan serta kebutuhan sehari-hari menjadi sangat terbatas; itu tanda keluarga yang tak seimbang","Proporsi terbalik — keinginan mendominasi, kebutuhan tidak cukup diamankan (sampai berutang), & tabungan minim; kebutuhan & tabungan harus didahulukan"],answer:2,explain:"Anggaran yang menempatkan keinginan di atas kebutuhan menghasilkan utang untuk hal yang seharusnya bisa dianggarkan, & tidak ada penyangga.",hint:"Bagian mana yang seharusnya diamankan lebih dulu & mendapat porsi lebih besar?"},
{n:96,type:"mcq",micro:"Kebutuhan, keinginan, & kebahagiaan",q:"Penelitian & pengalaman umum menunjukkan bahwa setelah kebutuhan dasar terpenuhi, kebahagiaan jangka panjang lebih dipengaruhi oleh...",options:["Hubungan, tujuan, kesehatan, pengalaman bermakna, & rasa cukup — daripada terus menambah barang","Jumlah barang yang dimiliki seseorang; makin banyak koleksi, makin besar kebahagiaannya dari waktu ke waktu","Merek barang yang dipakai sehari-hari; barang bermerek membuat pemakainya lebih bahagia sepanjang tahun"],answer:0,explain:"Mengejar keinginan materi tanpa henti jarang memberi kepuasan yang bertahan. Menyadari ini membantu menempatkan pengeluaran keinginan pada porsinya.",hint:"Apa yang membuat orang benar-benar puas dalam jangka panjang, setelah kebutuhan terpenuhi?"},
{n:97,type:"tf",micro:"Keputusan uang mencerminkan nilai",q:"Benar atau Salah: Cara seseorang membagi uangnya antara kebutuhan, tabungan, keinginan, & berbagi mencerminkan apa yang mereka anggap penting — & meninjaunya bisa membantu memastikan pengeluaran selaras dengan nilai mereka.",answer:true,explain:"Anggaran adalah 'pernyataan nilai dalam angka'. Ketidakcocokan antara nilai & pengeluaran adalah tanda untuk menyesuaikan.",hint:"Kalau kamu bilang keluarga penting tapi tidak pernah menyisihkan untuk hadiah/bantuan, apa yang ditunjukkan pengeluaranmu?"},
{n:98,type:"mcq",micro:"Inti yang dibawa pulang",q:"Satu gagasan inti tentang kebutuhan vs keinginan:",options:["Semua pengeluaran itu sama saja nilainya, jadi tak perlu membedakan kebutuhan dari keinginan, tak perlu menabung lebih dulu, dan tak perlu mengarahkan uang ke hal yang berarti, asal terpakai; uang memang untuk dihabiskan","Membedakannya dengan jujur & mengamankan kebutuhan & tabungan lebih dulu memberi kebebasan: kamu bisa menikmati keinginan tanpa cemas, menghadapi kejutan tanpa berutang, & mengarahkan uang ke hal yang benar-benar berarti bagimu","Keinginan harus dikalahkan oleh kebutuhan tanpa kecuali, jadi kita tak boleh menikmati hal menyenangkan dan tabungan dipakai hanya untuk menahan diri dari kebahagiaan sehari-hari; hidup lebih disiplin"],answer:1,explain:"Membedakan & memprioritaskan bukan tentang pantang, melainkan tentang kendali & kebebasan atas uangmu.",hint:"Apa yang kamu dapatkan dengan mengamankan kebutuhan & tabungan lebih dulu?"},
{n:99,type:"mcq",micro:"Menghubungkan ke keterampilan lain",q:"Membedakan kebutuhan & keinginan adalah dasar untuk keterampilan keuangan lain seperti...",options:["Tidak berhubungan dengan keterampilan keuangan lain; memilah pengeluaran hanyalah kebiasaan kecil yang berdiri sendiri tanpa kegunaan lanjutan","Hanya berguna untuk berbelanja di toko, sedangkan membuat anggaran, menabung, dan menghindari utang tak ada kaitannya dengan itu di rumah","Membuat anggaran, menabung untuk tujuan, menjadi konsumen cerdas, & menghindari utang yang tidak perlu — semuanya bergantung pada memilah pengeluaran"],answer:2,explain:"Hampir setiap keputusan keuangan dimulai dari 'apakah ini kebutuhan atau keinginan, & seberapa penting'.",hint:"Bisakah kamu membuat anggaran atau menabung untuk tujuan tanpa memilah pengeluaran?"},
{n:100,type:"open",micro:"Kapstone: panduan 'Kebutuhan vs Keinginan' untuk teman sebaya",q:"Tulis panduan singkat (8–10 poin) berjudul 'Kebutuhan atau Keinginan? Cara Memutuskan' untuk teman sebayamu. Cakup: definisi & cara membedakan (pertanyaan kunci), bahwa batasnya bisa bergeser menurut konteks, mengamankan kebutuhan & tabungan lebih dulu, keinginan itu sah tapi dikelola (jeda, batas, berbasis nilai), waspada iklan & tekanan sosial, kualitas untuk kebutuhan & 'nilai' untuk keinginan, biaya peluang, & meninjau pola secara berkala. Gunakan bahasa jelas & contoh konkret.",explain:"Panduan baik menyederhanakan semua prinsip: definisi & uji cepat, konteks yang menggeser batas, mengamankan kebutuhan & tabungan dulu, mengelola keinginan (jeda/batas/nilai), kewaspadaan pada iklan & tekanan, kualitas untuk kebutuhan, biaya peluang, & tinjauan berkala — dengan contoh ramah sebaya.",hint:"Tiap poin harus bisa langsung dipakai teman sebayamu di toko atau saat menerima uang saku.",sample:"Contoh panduan: 1) Kebutuhan = kamu perlukan untuk hidup, sehat, atau sekolah (makan, transport, alat wajib). Keinginan = menyenangkan tapi hidup tetap jalan tanpanya (jajan kekinian, mainan baru). Uji cepat: 'Apa masalahnya kalau aku TIDAK punya ini?' 2) Batasnya bisa geser: payung = keinginan di kemarau, lebih ke kebutuhan di musim hujan kalau jalan kaki. 3) Setiap kali dapat uang, amankan dulu kebutuhan (transport, makan) & tabungan — pisahkan di awal, jangan tunggu sisa. 4) Keinginan itu boleh! Tapi: tunggu 2 hari untuk yang di atas Rp25.000; tetapkan batas mingguan; lewati kalau tidak masuk anggaran. 5) Iklan & tren berusaha membuat keinginan terasa seperti kebutuhan ('kamu kurang tanpa ini'). Tanya: apakah aku benar-benar mau ini, atau takut berbeda? 6) Untuk kebutuhan, pilih yang cukup baik & tahan lama dengan harga wajar — bukan termurah yang cepat rusak, bukan termahal karena merek. 7) Untuk keinginan, 'nilai' = berapa lama kamu benar-benar akan menikmatinya ÷ harganya. 8) Setiap pembelian punya biaya peluang: uang untuk komik = tidak untuk tabungan sepeda. 9) Barang baru jarang menyembuhkan bosan/stres lama — perasaan itu biasanya kembali. 10) Sekali sebulan, cek: kebutuhan terpenuhi? nabung sesuai rencana? pengeluaran keinginan terasa sepadan? Sesuaikan bulan depan."},
];
